CREATE PROCEDURE [dbo].[sp_Build_Menu_Mix_Toast] -- Add the parameters for the stored procedure here 	( 		 @SDate date = null,          @EDate date = null,          @StoreGrouping int = 9,          @StoreGroup varchar(1500) = '192' 	) AS /** ## Procedure Name       *[toast].[dbo].[sp_Build_Menu_Mix_Toast]*   **Procedure Type**      *stored procedure*   **Author**              Wilson, Don < dwilson@newks.com >   **Version**             1   **Created**             20250728   **Summary**   *Populates the dev_aloha.dbo.MenuMix table each night   If manually run, it operates against the date range chosen at run time,   otherwise, it defaults to running for the last 14 days.*      ### Parameters   ```sql   SDate date                  Start date of the range   EDate date                  End Date of the range   StoreGrouping int           The grouping type of stores   StoreGroup varchar(1500)    The store / store group / dma / etc to run for   ```      ### Change History   **Change Date:**            *20200730*   **Author:**                 *Wilson, Don < dwilson@newks.com >*   **Version**:                3   **Change:**   *Add ModCode attribute to list of selected fields*      **Change Date:**            *20200319*   **Author:**                 *Wilson, Don < dwilson@newks.com >*   **Version**:                2   **Change:**   *Add documentation header*      -------------------     **/ BEGIN     -- SET NOCOUNT ON added to prevent extra result sets from     -- interfering with SELECT statements.     SET NOCOUNT ON;      declare          -- If this is for a table build, then Tab, if not, then Proc         @RunType varchar(4) = 'Tab'          -- The time the procedure begins running        ,@StartTime datetime = getdate()        -- The database the procedure is running in        ,@DBName varchar(150) = DB_NAME()        -- The name of the procedure itself        ,@ProcName varchar(150) = OBJECT_NAME(@@PROCID)        -- Default the error information to no error        ,@ErrorNumber int = 0        ,@ErrorMessage varchar(250) = ''        ,@ErrorLine int = 0             BEGIN TRY         	   SET @SDate = 		    CASE 			    WHEN @SDate IS NULL THEN convert(date,getdate()-14) 			    ELSE @SDate 		    END  	    SET @EDate = 		    CASE 			    WHEN @EDate IS NULL THEN convert(date,getdate()-1) 			    ELSE @EDate 		    END  		declare @Params varchar(2000) = (select @StoreGrouping as StoreGrouping, @StoreGroup as StoreGroup, @SDate as SDate, @EDate as EDate for json path)  	   select * 		into #StoresIncluded 		from dev_aloha.dbo.get_StoresIncluded ( @StoreGrouping, @StoreGroup, convert(date,getdate()-1))  		select 			convert(date,hgi.dateofbusiness) 'DateOfBusiness' 			, hgi.StoreNum 'fkstoreid' 			, sc.CategoryID 'FKCategoryId' 			, sc.ConsolCatID 'ConsolCat' 			, doom.OrderModeID 'FKOrderModeId' 			, hgi.ParentID 			, hgi.ItemID 'fkitemid' 			, pm.ModCodeID 'modcode' 			, ItemHour = datepart(hour,hgi.SystemTime) 			, ItemMinute =  				case 					when datepart(minute, hgi.SystemTime) between 0 and 14 then 0 					when datepart(minute, hgi.SystemTime) between 15 and 29 then 15 					when datepart(minute, hgi.SystemTime) between 30 and 44 then 30 					when datepart(minute, hgi.SystemTime) between 45 and 59 then 45 				end 			, max(hgi.price) 'Price' 			, sum(hgi.price) Gross 			, sum(hgi.DiscPric) Net 			, sum(hgi.Quantity) ItemCount 			, convert(float,0) 'EntreeEquiv' 		into #MM 		from toast.dbo.hstItem hgi 		join toast.dbo.cfg_map_DiningOptionToOrderMode doom 		on hgi.OrderMode = doom.GUID 		join toast.dbo.cfg_menu_items mi 		on hgi.MenuItemMLI = mi.MultiLocationId 		and hgi.StoreNum = mi.StoreNum 		join toast.dbo.cfg_map_Sales_Cats sc 		on hgi.SalesCategoryGUID = sc.CAT_GUID 		join toast.dbo.cfg_PreModifier pm 		on hgi.PreModifier = pm.GUID 		join #StoresIncluded si 		on mi.StoreNum = si.StoreID 		where Deferred = 0 		and Voided = 0 		and DateOfBusiness between @SDate and @EDate 		group by hgi.DateOfBusiness, hgi.StoreNum, sc.CategoryID, sc.ConsolCatID, doom.OrderModeID, hgi.ParentID, hgi.ItemID, pm.ModCodeID, datepart(hour,hgi.SystemTime), datepart(minute, hgi.SystemTime), mi.guest_count 		order by hgi.DateOfBusiness, hgi.StoreNum, sc.CategoryID, sc.ConsolCatID, doom.OrderModeID, hgi.ParentID, hgi.ItemID, pm.ModCodeID, datepart(hour,hgi.SystemTime), datepart(minute, hgi.SystemTime)   		update #MM set 			EntreeEquiv = TRY_CAST(substring(j.name, 4, LEN(j.name)-3) AS DECIMAL(3,1)) 		from #MM mm 		join toast.dbo.cfg_menu_items_master mi 		on mm.fkitemid = mi.Item_PLU 		cross apply 			openjson(item_tags) 			with (guid char(36) '$.guid', 				  name varchar(75) '$.name' 			) as j 		where j.name like 'EE%'          -- if this is a table build, perform it as a transaction 		if (@RunType = 'Tab') 		begin 			begin transaction;			         				DELETE FROM toast.dbo.MenuMix 				WHERE DateOfBusiness BETWEEN @SDate AND @EDate 				and fkstoreid in (select storeid from #StoresIncluded)  				INSERT INTO toast.dbo.MenuMix 				SELECT * FROM #MM 				ORDER BY dateofbusiness, fkstoreid, fkcategoryid, fkordermodeid, parentid, fkitemid, ItemHour, ItemMinute          			-- If the table build has no error, then commit the transaction 			commit transaction;    		end 	    	   DROP TABLE #StoresIncluded 	   DROP TABLE #MM                       -- Log the successful completion         exec Logging.dbo.Write_Procedure_Execution              @RunType = @RunType             ,@StartTime = @StartTime             ,@DBName = @DBName             ,@ProcName = @ProcName 			,@Params = @Params;                  END TRY     BEGIN CATCH         -- If there are errors and a transaction was started, roll it back         IF @@TRANCOUNT > 0         ROLLBACK TRANSACTION;                  -- Record the error details         set @ErrorNumber  = ERROR_NUMBER();         set @ErrorLine  = ERROR_LINE();         set @ErrorMessage  = ERROR_MESSAGE();                  -- Log the error         exec Logging.dbo.Write_Procedure_Execution              @RunType = @RunType             ,@StartTime = @StartTime             ,@DBName = @DBName             ,@ProcName = @ProcName             ,@ErrorNumber = @ErrorNumber             ,@ErrorMessage = @ErrorMessage             ,@ErrorLine = @ErrorLine 			,@Params = @Params;          THROW;     END CATCH END